DROP TABLE IF EXISTS `change_attachments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `change_attachments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `change_id` int NOT NULL,
  `uploaded_by` int NOT NULL,
  `filename` varchar(255) NOT NULL,
  `storage_key` varchar(64) NOT NULL,
  `storage_backend` varchar(16) NOT NULL DEFAULT 'local',
  `storage_bucket` varchar(63) NOT NULL DEFAULT '',
  `extension` varchar(10) NOT NULL,
  `content_type` varchar(100) NOT NULL,
  `size` int NOT NULL,
  `sha256` varchar(64) NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `storage_key` (`storage_key`),
  KEY `uploaded_by` (`uploaded_by`),
  KEY `ix_change_attachments_change_id` (`change_id`),
  CONSTRAINT `change_attachments_ibfk_1` FOREIGN KEY (`change_id`) REFERENCES `change_requests` (`id`) ON DELETE CASCADE,
  CONSTRAINT `change_attachments_ibfk_2` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
